#!/usr/bin/env node

/**
 * Concatenates the migrations that production is missing into one ordered file
 * that can be pasted into the Supabase SQL editor in a single run.
 *
 * Produced rather than hand-maintained so it cannot drift from the migrations
 * themselves. Each file keeps its own BEGIN/COMMIT, so a failure rolls that
 * migration back without affecting the ones already committed before it, and
 * the run stops there.
 *
 * Usage: node scripts/build-pending-migration-bundle.mjs [outFile]
 *        (default: pending-migrations.sql, which is gitignored)
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = process.cwd();
const OUT = resolve(ROOT, process.argv[2] || "pending-migrations.sql");

/**
 * Ordered list of what production is missing, measured with
 * `npm run check:drift` on 2026-08-22. Re-run that before trusting this.
 *
 * 20260820163000_confirm_test_user_email is deliberately excluded: it grants
 * EXECUTE on a SECURITY DEFINER auth writer to anon. See
 * docs/HANDOFF-production-tasks.md section 5.
 */
const PENDING = [
  {
    file: "20260812130000_free_tiers_and_access_hardening.sql",
    note: "Seeds the default free packages. Unblocks colleges reading applications.",
  },
  {
    file: "20260817193000_public_competition_access_hardening.sql",
    note: "Policy only, and the one file with no transaction of its own — wrapped below.",
    wrap: true,
  },
  {
    file: "20260817230000_multi_role_support.sql",
    note: "Adds the admin-gated grant/revoke role RPCs.",
  },
  {
    file: "20260821120000_harden_confirm_test_user_email.sql",
    note: "No-op on production; keeps the ledger honest and protects other environments.",
  },
  {
    file: "20260822120000_admin_delete_policies.sql",
    note: "Adds the missing DELETE policies on profiles and packages.",
  },
  {
    file: "20260822130000_reconcile_page_sections_columns.sql",
    note: "REQUIRED. No other migration can add these columns. Apply this even if you skip the rest.",
  },
];

const rule = (text) => `-- ${"=".repeat(74)}\n-- ${text}\n-- ${"=".repeat(74)}`;

const parts = [
  rule("PENDING PRODUCTION MIGRATIONS"),
  `--
-- Generated by scripts/build-pending-migration-bundle.mjs
-- Run this in the Supabase SQL editor, top to bottom, in one go.
--
-- Before starting: confirm a recent backup or PITR window in Database → Backups.
-- The first migration mutates live rows in packages, sub_admin_requests and
-- site_settings.
--
-- Each migration keeps its own BEGIN/COMMIT. If one fails it rolls itself back
-- and execution stops there; migrations already committed above it stay applied.
--
-- Deliberately NOT included: 20260820163000_confirm_test_user_email.sql, which
-- grants EXECUTE on a SECURITY DEFINER auth writer to anon.
-- See docs/HANDOFF-production-tasks.md section 5.
--`,
];

let count = 0;
for (const { file, note, wrap } of PENDING) {
  const path = resolve(ROOT, "supabase/migrations", file);
  if (!existsSync(path)) {
    console.error(`✖ Missing migration file: ${file}`);
    process.exit(1);
  }
  const sql = readFileSync(path, "utf8").trim();
  count += 1;

  parts.push("");
  parts.push(rule(`${count}. ${file}`));
  parts.push(`-- ${note}`);
  parts.push("");
  parts.push(wrap ? `BEGIN;\n\n${sql}\n\nCOMMIT;` : sql);
}

parts.push("");
parts.push(rule("BOOKKEEPING — run this last"));
parts.push(`--
-- Applying SQL by hand does not update supabase_migrations.schema_migrations,
-- the ledger the CLI reads. Without this, a later \`supabase db push\` will try
-- to replay every file above.
--
-- 20260820163000 is deliberately omitted. Leaving it unrecorded is what stops a
-- future push from quietly introducing the anon grant.
--`);
parts.push("");
parts.push(`insert into supabase_migrations.schema_migrations (version)
values ${PENDING.map((p) => `('${p.file.slice(0, 14)}')`).join(",\n       ")}
on conflict (version) do nothing;`);
parts.push("");
parts.push(rule("VERIFY"));
parts.push(`-- Expect page_sections to have both columns:
select column_name
from   information_schema.columns
where  table_schema = 'public' and table_name = 'page_sections'
  and  column_name in ('parent_id', 'extra_data');

-- Expect college-free among the seeded free tiers:
select code, package_kind, is_default_free
from   public.packages
where  package_kind = 'free'
order  by code;

-- Then run \`npm run check:drift\` locally; it should report no drift.`);
parts.push("");

writeFileSync(OUT, parts.join("\n"));

console.log(`✔ Wrote ${OUT}`);
console.log(`  ${count} migrations, in order, with bookkeeping and verification appended.`);
console.log("  Re-run `npm run check:drift` first if this is more than a few days old.");
